argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32Dlg {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd,int n);
}
"@
$desktop=[System.Windows.Automation.AutomationElement]::RootElement
$wins=$desktop.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition)
$dlg=$null
for($i=0;$i -lt $wins.Count;$i++){
  $w=$wins.Item($i)
  $cls=[string]$w.Current.ClassName
  $name=[string]$w.Current.Name
  if($cls -eq '#32770' -or $name -match '開啟|Open|選取|檔案'){ $dlg=$w; break }
}
if($null -eq $dlg){throw 'No file picker dialog found'}
[W32Dlg]::ShowWindow([IntPtr]$dlg.Current.NativeWindowHandle,9)|Out-Null
[W32Dlg]::SetForegroundWindow([IntPtr]$dlg.Current.NativeWindowHandle)|Out-Null
Start-Sleep -Milliseconds 250
$all=$dlg.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$edits=@()
$buttons=@()
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  $ct=$e.Current.ControlType
  if($ct -eq [System.Windows.Automation.ControlType]::Edit){
    $r=$e.Current.BoundingRectangle
    if(-not [double]::IsInfinity($r.Y)){$edits += [pscustomobject]@{e=$e;y=$r.Y;name=[string]$e.Current.Name;aid=[string]$e.Current.AutomationId}}
  } elseif($ct -eq [System.Windows.Automation.ControlType]::Button){
    $buttons += $e
  }
}
if($edits.Count -eq 0){throw 'No editable field in file picker'}
$fileEdit=$edits | Sort-Object y -Descending | Select-Object -First 1 | ForEach-Object {$_.e}
$fileEdit.SetFocus()
Set-Clipboard -Value 'C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg'
[System.Windows.Forms.SendKeys]::SendWait('^a')
[System.Windows.Forms.SendKeys]::SendWait('^v')
Start-Sleep -Milliseconds 300
$openBtn=$null
foreach($b in $buttons){
  $n=[string]$b.Current.Name
  if($n -match '^開啟$|^Open$|^選取$'){ $openBtn=$b; break }
}
if($null -ne $openBtn){
  $inv=$openBtn.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
  $inv.Invoke()
}else{
  [System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
}
Start-Sleep -Seconds 6
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible after picker'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all2=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all2.Count;$i++){
  $e=$all2.Item($i)
  $ct=$e.Current.ControlType.ProgrammaticName
  $name=[string]$e.Current.Name
  if(($ct -match 'Button|Edit|Text|Image') -and $name){
    $r=$e.Current.BoundingRectangle
    if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 350 -and $r.Y -lt 850){
      $out += [pscustomobject]@{type=$ct;name=$name;aid=[string]$e.Current.AutomationId;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height;enabled=[bool]$e.Current.IsEnabled}
    }
  }
}
[pscustomobject]@{dialog_name=[string]$dlg.Current.Name;controls=$out}|ConvertTo-Json -Depth 6 -Compress
